var n={en:`Clients reserve tutors, cleaners and technicians. Providers set prices and availability; the platform handles booking, payment, cancellations and verified reviews.`,ua:`Клієнти бронюють репетиторів, прибиральників і майстрів. Виконавці задають ціни й графіки; платформа обробляє бронювання, оплату, скасування й перевірені відгуки.`};var a={en:[`Draw buyers, sellers, listings, bookings, settlement, reviews and notifications.`,`Identify the authoritative owner of each time slot.`,`Model payment hold, cancellation and verified-review eligibility.`],ua:[`Намалюй покупців, виконавців, оголошення, бронювання, розрахунки, відгуки та сповіщення.`,`Визнач джерело істини для часових слотів.`,`Змоделюй утримання грошей, скасування й право на відгук.`]};var t=[{en:`One slot cannot be booked twice.`,ua:`Один слот не бронюється двічі.`},{en:`Only eligible completed bookings can produce verified reviews.`,ua:`Підтверджені відгуки пов’язані з придатними завершеними бронюваннями.`}];var s={scenario:n,tasks:a,checks:t};export{t as checks,s as default,n as scenario,a as tasks};